#!/bin/zsh
# Display and accessibility state of the runner (generated by tools/mac/ci.py, decision #171).
#   display.sh set DIR         switch Reduce Motion / Reduce Transparency off, build the probe in DIR, assert
#   display.sh check DIR OUT   read again, copy the record to OUT/display.txt, assert
#   display.sh reduce DIR LIST switch on what LIST names (reduce-motion, reduce-transparency, comma-separated),
#                              the other one off, and assert exactly that (one suite's reduced run, decision #173)
#   display.sh normal DIR      both off again, assert
set -u
mode=${1:?set, check, reduce or normal}; dir=${2:?probe directory}; mkdir -p $dir
log=$dir/display.txt
write() {  # motion transparency (true|false each)
  defaults write com.apple.universalaccess reduceMotion -bool $1 >> $log 2>&1; echo "write universalaccess reduceMotion $1: exit $?" >> $log
  defaults write com.apple.universalaccess reduceTransparency -bool $2 >> $log 2>&1; echo "write universalaccess reduceTransparency $2: exit $?" >> $log
  defaults write com.apple.Accessibility ReduceMotionEnabled -bool $1 >> $log 2>&1; echo "write Accessibility ReduceMotionEnabled $1: exit $?" >> $log
  defaults write com.apple.Accessibility EnhancedBackgroundContrastEnabled -bool $2 >> $log 2>&1; echo "write Accessibility EnhancedBackgroundContrastEnabled $2: exit $?" >> $log
}
reads() {  # motion transparency: the last reading says exactly this
  [[ "$(grep '^reduceMotion:' $log | tail -1)" == "reduceMotion: $1" &&
     "$(grep '^reduceTransparency:' $log | tail -1)" == "reduceTransparency: $2" ]]
}
if [[ $mode == reduce ]]; then
  list=",${3:?reduce-motion and/or reduce-transparency},"; motion=false; transparency=false
  [[ $list == *,reduce-motion,* ]] && motion=true
  [[ $list == *,reduce-transparency,* ]] && transparency=true
  if [[ $motion == false && $transparency == false ]]; then echo "display: nothing to switch on in '$3'"; exit 1; fi
  write $motion $transparency
  echo "--- for one suite: reduceMotion $motion, reduceTransparency $transparency" >> $log
  $dir/display-probe >> $log 2>&1
  if reads $motion $transparency; then
    echo "display: this suite runs with reduceMotion $motion, reduceTransparency $transparency"; exit 0
  fi
  echo "display: the switches did not take"; tail -12 $log; exit 1
fi
if [[ $mode == normal ]]; then
  write false false
  echo "--- back to normal" >> $log
  $dir/display-probe >> $log 2>&1
  if reads false false; then exit 0; fi
  tail -12 $log; exit 1
fi
read_state() {  # label
  echo "--- $1" >> $log
  $dir/display-probe >> $log 2>&1
  tail -8 $log
}
normal() {  # the last reading says both switches are off
  [[ "$(grep '^reduceMotion:' $log | tail -1)" == "reduceMotion: false" &&
     "$(grep '^reduceTransparency:' $log | tail -1)" == "reduceTransparency: false" ]]
}
if [[ $mode == set ]]; then
  cat > $dir/display-probe.swift <<'SWIFT'
import AppKit
_ = NSApplication.shared
let workspace = NSWorkspace.shared
print("reduceMotion: \(workspace.accessibilityDisplayShouldReduceMotion)")
print("reduceTransparency: \(workspace.accessibilityDisplayShouldReduceTransparency)")
print("increaseContrast: \(workspace.accessibilityDisplayShouldIncreaseContrast)")
print("differentiateWithoutColor: \(workspace.accessibilityDisplayShouldDifferentiateWithoutColor)")
print("screens: \(NSScreen.screens.map { "\($0.frame.size) scale \($0.backingScaleFactor)" })")
SWIFT
  swiftc -O -o $dir/display-probe $dir/display-probe.swift || { echo "display: the probe does not compile"; exit 1; }
  : > $log
  sw_vers >> $log 2>&1
  for key in "com.apple.universalaccess reduceMotion" "com.apple.universalaccess reduceTransparency" \
             "com.apple.Accessibility ReduceMotionEnabled" "com.apple.Accessibility EnhancedBackgroundContrastEnabled"; do
    echo "defaults $key = $(defaults read ${=key} 2>&1 | tail -1)" >> $log
  done
  read_state "as the image came"
  write false false
  read_state "after defaults write"
  if ! normal; then
    killall cfprefsd >> $log 2>&1; sleep 2
    read_state "after restarting cfprefsd"
  fi
  if ! normal; then
    launchctl kickstart -k gui/$(id -u)/com.apple.universalaccessd >> $log 2>&1; sleep 2
    read_state "after restarting universalaccessd"
  fi
else
  out=${3:?output directory}; mkdir -p $out
  read_state "before the suites"
  cp $log $out/display.txt
fi
if normal; then
  echo "display: Reduce Motion and Reduce Transparency are off"
else
  echo "display: Reduce Motion or Reduce Transparency is still on; the suites would take the reduced branch (decision #171)"
  cat $log
  exit 1
fi
